from pathlib import Path
import json
HERE=Path(__file__).resolve().parent
targets=json.loads((HERE/'local_baseline.json').read_text(encoding='utf-8'))['targets']
identities={
 'Bat':'Small olive-brown cartoon flying bat, huge pointed ears with muted tan inner ears, cream eyes, tiny ochre piglike nose, two ivory fangs, compact round body with small dangling claws, dark brown ribbed leathery wings. Preserve the original olive and ochre palette, not purple or blue. No tail.',
 'BattlePanther':'Low-slung muscular dark olive-brown armored panther, cream muzzle and underside, gold facial marks, heavy angular brows, small triangular ears, thick dark outlines, yellow-ochre saddle with silver-gray raised armor plates and rivets, stout paws and a long banded gold-and-brown tail. Preserve exact saddle and metal design. No rider, no new weapons.',
 'Bear':'Stocky shaggy ochre-brown bear with large blocky furry head, small round ears, stern cream eyes, dark broad nose, cream muzzle and visible fangs; broad shoulders, four thick rounded furry paws, small short tapered tail. No saddle or armor.',
 'BearMounted':'The source is an ochre-brown shaggy bear wearing an ochre leather saddle and chest/girth straps, rectangular flap, two silver rivets, metal buckle and stirrup. There is NO rider. Preserve the saddle, straps and silhouette, four stocky paws, short tail, dark nose, cream muzzle and fangs. Do not add a person.',
 'BlackBear':'Shaggy dark charcoal-olive bear, darker than Bear, with sparse ochre spots and highlights across its pelt, cream muzzle and stern eyes, black-brown nose, coarse cheek fur, four stout clawed paws and a short dark tapered tail. No saddle. Preserve dark source palette, not jet black.',
 'BlackBoar':'Round squat dark olive-gray boar with ochre mottled spots, short bristly mane, huge cream eyes, broad tan-gray snout, two ivory upward tusks, dark small hooves and characteristic pale stitched scars on its back and forehead. Keep the scars and dark palette. No saddle.',
 'BlackWolf':'Lean shaggy dark olive-brown wolf with long angular muzzle, black nose, large cream eyes, triangular pointed ears, ochre highlights on face and feet, fangs, four short sturdy paws and long bushy dark tail with ochre tip. No saddle or armor. Keep its lean body and bushy tail.',
 'BlueScorpion':'Despite its filename the CURRENT source is GOLDEN OCHRE, not blue. Golden segmented scorpion with thick dark olive-brown outlines, layered oval back plates, six thin jointed walking legs (three pairs), two huge curved pincers, small head with ivory eyes and two short front horns, a large segmented upward-curled tail ending in an ochre stinger. Match current gold source exactly, no recoloring.',
 'Boar':'Round squat ochre-brown boar, cream eyes and snout highlights, two large ivory upward tusks, small triangular ears, short dark spiky back mane, ochre spots, four tiny dark rounded hooves and a tiny tail nub. No saddle, no scars.',
 'BoarMounted':'The source is a round ochre-brown boar with a crosshatched leather saddle pad, ochre rim, dark brown girth strap, small silver rivet and hanging stirrup. There is NO rider. Keep cream eyes, tan snout, two ivory upward tusks, short bristly mane, ochre spots, four tiny dark hooves and small tail nub. Do not add a person.'
}
for target in targets:
 name=target['name']
 for direction in ['Up','Down']:
  view='REAR / BACK view, travelling AWAY toward screen UP. The viewer sees the back of the head and ears, dorsal back, rump and tail. NO eyes, nose, mouth or facial features are visible on any rear head. All three rear head expression slots share the same back silhouette.' if direction=='Up' else 'FRONT view, travelling TOWARD the viewer toward screen DOWN. Both eyes, muzzle and symmetric anatomy face the viewer. Show normal, attack-angry and dead head expressions with identical anatomy, scale and alignment.'
  if name=='Bat':
   slots='A FOUR column by TWO row grid. Row 1 left-to-right: (1) detached normal head, (2) detached angry head, (3) detached dead head, (4) detached compact torso including tiny dangling feet, NO head or wings. Row 2: (5) detached LEFT wing fully raised, (6) detached LEFT wing spread/lowered, (7) completely empty magenta, (8) completely empty magenta. Each wing has its shoulder attachment at the RIGHT edge and fans toward the LEFT. Its two poses must preserve the same skin, ribs and outline. Both head ears stay inside each head slot.'
  elif name=='BlueScorpion':
   slots='A THREE column by THREE row grid. Row 1: (1) detached normal head, (2) detached angry head, (3) detached dead head. Row 2: (4) detached segmented torso/back plates only, NO head, legs, claws or tail; (5) ONE detached left front walking leg, (6) ONE detached left middle walking leg. Row 3: (7) ONE detached left rear walking leg, (8) ONE detached complete LEFT pincer/arm including both curved jaws and its connection root on the RIGHT edge, (9) detached complete segmented curled tail WITH stinger, root at BOTTOM center, curling UP. Keep all six leg positions anatomically possible; only one limb per leg slot for mirroring.'
  else:
   slots='A FOUR column by TWO row grid. Row 1 left-to-right: (1) detached normal head with ears, (2) detached angry head, (3) detached dead head, (4) detached torso/back and rump ONLY, with original saddle/armor/straps if present, but NO head, tail or legs. Row 2: (5) ONE detached left FORELEG with paw/hoof, (6) ONE detached left HINDLEG with paw/hoof, (7) detached tail including its attachment root, (8) completely empty magenta. Legs point downward, rounded upper roots attach behind the torso, feet point in the actual travel direction. Foreleg and hindleg must be separately designed for this view. Only one leg per slot; the other side is mirrored by the game.'
  prompt=f'''Use case: identity-preserve. Production 2D game sprite PARTS, not concept art.
Image 1 is the authoritative CURRENT ORIGINAL atlas; Image 2 is a complete character reconstructed by rendering the CURRENT original prefab's serialized sprites, positions, scales, pivots and draw order. Use BOTH as the identity and style references. The second is an offline reference, not a new character design.
Character: {name}. {identities[name]}
Requested camera: {view} Keep the game's elevated orthographic cartoon perspective: visible upper back on a quadruped, front paws in front of rear paws, correct leg joints and rump/tail connections. This must be a newly drawn matching view, never a rotated, vertically flipped or stretched side sprite.
Output exactly ONE clean sprite parts sheet. {slots}
Every part is isolated in the center of its own equal grid cell with 12 percent empty padding on every side. Do not draw grid lines or labels. No part crosses any cell boundary. Keep normal/angry/dead heads at the SAME exact size and alignment. A body slice is a complete solid torso with clean rounded neck/leg connections, not an assembled animal. A head slice contains the full head only, no torso, limbs or background remnants. Use near-symmetric front/back anatomy without copying side facing poses.
Match source palette, broad simple shaded color regions, flat cartoon cel shading, heavy smooth dark brown outlines, original material and proportions. Preserve species-specific ears, horns, fur, tail, saddle or armor visible from this direction. NO borrowed chicken combs, feathers, wings on mammals, no new equipment and no rider.
Background is completely flat pure RGB #FF00FF magenta. All animal interiors must be opaque solid source colors; no magenta holes. No floor, NO ground shadow, NO cast shadow, no glow, no gradients on the background, no watermark, no text, no diagram arrows, no extra complete character. Deliver crisp intact outlines suitable for removing magenta and using as transparent PNG sprites.
'''
  directory=HERE/name/'generation'/direction;directory.mkdir(parents=True,exist_ok=True)
  if not (directory/'request.json').exists():
   prompt += '\nThe background must be exactly #FF00FF immediately outside each dark outline. Absolutely NO soft shadow, vignette, dark glow, blurry halo, airbrush or painterly texture. Flat source-style hard-edged sprites only.\n'
   (directory/'prompt.txt').write_text(prompt,encoding='utf-8')
print('Prepared complete per-character/per-direction prompts in Docs only.')
